#include <fstream>
#include <vector>
using namespace std;
int main() {
    ifstream in("gymnastics.in"); ofstream out("gymnastics.out");
    int k, n; if (!(in >> k >> n)) return 0;
    vector<vector<int>> position(k, vector<int>(n + 1));
    vector<int> first(n);
    for (int session = 0; session < k; ++session)
        for (int rank = 0; rank < n; ++rank) {
            int cow; in >> cow; position[session][cow] = rank;
            if (session == 0) first[rank] = cow;
        }
    int answer = 0;
    for (int i = 0; i < n; ++i) for (int j = i + 1; j < n; ++j) {
        bool consistent = true;
        for (int session = 1; session < k; ++session)
            if (position[session][first[i]] > position[session][first[j]]) consistent = false;
        answer += consistent;
    }
    out << answer << '\n';
}
