#include <set>
#include <string>
using namespace std;
int main() {
    ifstream in("whereami.in"); ofstream out("whereami.out");
    int n; string s; if (!(in >> n >> s)) return 0;
    for (int length = 1; length <= n; ++length) {
        set<string> windows;
        bool unique = true;
        for (int start = 0; start + length <= n; ++start)
            if (!windows.insert(s.substr(start, length)).second) { unique = false; break; }
        if (unique) { out << length << '\n'; return 0; }
    }
}
