    sort(names.begin(), names.end());
    int n; if (!(in >> n)) return 0;
    vector<pair<int, int>> constraints;
    for (int i = 0; i < n; ++i) {
        string a, b, word; in >> a;
        for (int j = 0; j < 4; ++j) in >> word;
        in >> b;
        constraints.emplace_back(int(find(names.begin(), names.end(), a) - names.begin()),
                                 int(find(names.begin(), names.end(), b) - names.begin()));
    }
    array<int, 8> order; iota(order.begin(), order.end(), 0);
    do {
        array<int, 8> position;
        for (int i = 0; i < 8; ++i) position[order[i]] = i;
        bool valid = true;
        for (auto [a, b] : constraints) if (abs(position[a] - position[b]) != 1) valid = false;
        if (valid) { for (int cow : order) out << names[cow] << '\n'; return 0; }
    } while (next_permutation(order.begin(), order.end()));
}
